sols = []
for a in range(1, 100):
    for b in range(1, 100):
        # use log comparison to filter, then exact for small
        try:
            if b*b*__import__('math').log(a) == a*__import__('math').log(b):
                # exact check
                if a**(b*b) == b**a:
                    sols.append((a,b))
        except:
            pass
print('log-based candidates done')
# exact small
sols2 = []
for a in range(1, 60):
    for b in range(1, 60):
        if a**(b*b) == b**a:
            sols2.append((a,b))
print('exact:', sols2)
"

